def derive_subdomain(entry):
    blob = " ".join([entry.get("goal",""), entry.get("summary",""),
                     " ".join(s.get("command","") for s in entry.get("steps",[]))])
    for pat, sub in KEYWORD_SUBDOMAIN:
        if re.search(pat, blob, re.I):
            return sub
    return DOMAIN_DEFAULT.get(entry.get("domain",""), entry.get("domain","general"))

with open(JSON_PATH, encoding="utf-8") as f: data = json.load(f)
with open(JSONL_PATH, encoding="utf-8") as f: jsonl_lines = [l for l in f if l.strip()]

retro = 0
for d in data:
    if "subdomain" not in d:
        # keep field order sensible: insert after domain
        sub = derive_subdomain(d)
        new = {}
        for k, v in d.items():
            new[k] = v
            if k == "domain": new["subdomain"] = sub
        d.clear(); d.update(new); retro += 1
print(f"[PART 1] subdomain added to {retro} existing records")

