existing_ids = set(d["id"] for d in data)
existing_goals = set(d["goal"] for d in data)
prefix_index = collections.defaultdict(list)
for g in existing_goals: prefix_index[' '.join(g.lower().split()[:4])].append(g)

base = datetime(2026, 8, 9, 9, 0, 0)
added = skipped = 0
for i, (dom, sub, goal, plan, cmds, resolved, summary, rec, fb) in enumerate(NEW):
    if goal in existing_goals: skipped += 1; continue
    created = base + timedelta(minutes=7*i)
    steps = [{"command": c, "blocked": False, "exitCode": ec, "stdout": o, "stderr": e, "reason": None}
             for c, ec, o, e in cmds]
    entry = {
        "id": str(uuid.uuid4()),
        "createdAt": created.strftime("%Y-%m-%dT%H:%M:%S.000Z"),
        "goal": goal, "domain": dom, "subdomain": sub,
        "plan": list(plan), "steps": steps, "resolved": resolved,
        "summary": summary, "recommendation": rec,
        "feedback": {"worked": fb[0], "note": fb[1],
                     "at": (created+timedelta(minutes=4)).strftime("%Y-%m-%dT%H:%M:%S.000Z")}
    }
    data.append(entry); existing_goals.add(goal); added += 1
    cmd_lines = "\n".join(f"- {c[0]}" + ("  [FAILED: "+c[3][:70]+"]" if c[1]!=0 else "") for c in cmds)
    status = "" if resolved else "\nNOTE: not resolved - see recommendation."
    jsonl_lines.append(json.dumps({"messages":[
        {"role":"system","content":f"You are a Windows repair expert specializing in {dom} ({sub}) problems. Diagnose with read-only commands first, then apply safe fixes. When a command fails, interpret the error and adapt."},
        {"role":"user","content":goal},
        {"role":"assistant","content":f"{summary}\nCommands used:\n{cmd_lines}\nRecommendation: {rec}{status}"}]}, ensure_ascii=False)+"\n")

with open(JSON_PATH,"w",encoding="utf-8") as f: json.dump(data,f,indent=2,ensure_ascii=False); f.write("\n")
with open(JSONL_PATH,"w",encoding="utf-8") as f: f.writelines(jsonl_lines)

print(f"[PART 2] new records: {added} | skipped dup: {skipped}")
print("Total JSON:", len(data), "| Total JSONL:", len(jsonl_lines))
print("unresolved records now:", sum(1 for d in data if not d.get("resolved", True)))
print("feedback worked=false:", sum(1 for d in data if d.get("feedback",{}).get("worked") is False))
print("records with subdomain:", sum(1 for d in data if "subdomain" in d))
print("distinct subdomains:", len(set(d.get("subdomain") for d in data)))
